def get_commitment_point_stats(traces: List[Dict]) -> Dict[str, Any]:
    """Compute statistics about commitment point distribution."""
    cps = [t["commitment_point"] for t in traces if t["commitment_point"] is not None]
    num_steps_list = [t["num_steps"] for t in traces if t["commitment_point"] is not None]

    if not cps:
        return {"count": 0}

    cps_arr = np.array(cps)
    ns_arr = np.array(num_steps_list)
    rel = cps_arr / ns_arr

    return {
        "count": len(cps_arr),
        "mean": float(np.mean(cps_arr)),
        "median": float(np.median(cps_arr)),
        "std": float(np.std(cps_arr)),
        "min": int(np.min(cps_arr)),
        "max": int(np.max(cps_arr)),
        "relative_position_mean": float(np.mean(rel)),
        "relative_position_median": float(np.median(rel)),
        "relative_position_std": float(np.std(rel)),
    }
